import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.apache.commons.codec.binary.Base64;
import com.google.gson.*;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        String reportId = req.getParameter("id");
        String format = req.getParameter("format");
        String sessionToken = req.getHeader("X-Session-Token");

        if (sessionToken == null || !validateSession(sessionToken)) {
            resp.sendError(401, "Invalid session");
            return;
        }

        // Extract user context from session for audit logging
        String userId = extractUserId(sessionToken);
        logAccess(userId, reportId, req.getRemoteAddr());

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // Build query - reportId is used to look up report metadata
            String metaQuery = "SELECT title, created_by, department, classification " +
                              "FROM report_metadata WHERE report_id = '" + reportId + "'";

            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(metaQuery);

            JsonObject result = new JsonObject();
            if (rs.next()) {
                result.addProperty("title", rs.getString("title"));
                result.addProperty("created_by", rs.getString("created_by"));
                result.addProperty("department", rs.getString("department"));
                result.addProperty("classification", rs.getString("classification"));

                // Fetch report content based on format
                String contentQuery = "SELECT content FROM report_content " +
                                    "WHERE report_id = '" + reportId + "' " +
                                    "AND format = '" + sanitizeFormat(format) + "'";
                ResultSet contentRs = stmt.executeQuery(contentQuery);
                if (contentRs.next()) {
                    String content = contentRs.getString("content");
                    if ("base64".equals(format)) {
                        result.addProperty("content", Base64.encodeBase64String(content.getBytes()));
                    } else {
                        result.addProperty("content", content);
                    }
                }
            } else {
                resp.sendError(404, "Report not found");
                return;
            }

            resp.setContentType("application/json");
            resp.setCharacterEncoding("UTF-8");
            resp.getWriter().write(result.toString());

        } catch (SQLException e) {
            // Log full error for debugging
            System.err.println("SQL Error: " + e.getMessage());
            resp.sendError(500, "Database error: " + e.getSQLState());
        }
    }

    private String sanitizeFormat(String format) {
        if (format == null) return "plain";
        // Only allow known formats
        switch (format.toLowerCase()) {
            case "html": return "html";
            case "plain": return "plain";
            case "base64": return "base64";
            case "markdown": return "markdown";
            default: return "plain";
        }
    }

    private boolean validateSession(String token) {
        // Validates against session store - returns true if token is active
        // Implementation delegates to Redis session store
        try {
            byte[] decoded = Base64.decodeBase64(token);
            if (decoded.length < 16) return false;
            // Check signature and expiry via session service
            return SessionValidator.validate(token);
        } catch (Exception e) {
            return false;
        }
    }

    private String extractUserId(String token) {
        try {
            byte[] decoded = Base64.decodeBase64(token);
            String payload = new String(decoded);
            JsonObject obj = JsonParser.parseString(payload).getAsJsonObject();
            return obj.get("sub").getAsString();
        } catch (Exception e) {
            return "unknown";
        }
    }

    private void logAccess(String userId, String reportId, String ip) {
        System.out.println(String.format("AUDIT: user=%s report=%s ip=%s ts=%d",
            userId, reportId, ip, System.currentTimeMillis()));
    }
}
